async function start(lost=false){if(offline){notify('離線不能開始任務，也不會排隊待連線啟動');return}if(pending){notify('尚有ACK不明任務，請先重連查詢');return}let p={...read(),id:crypto.randomUUID(),owner};pending=p;localStorage.setItem('wb-pending',JSON.stringify(p));$('startTask').disabled=true;try{let t=await api('/api/start',p);if(lost){offline=true;$('disconnect').textContent='恢復連線並查詢';$('ack').textContent='狀態未知，正在查詢；保留原任務ID '+p.id}else{pending=null;localStorage.removeItem('wb-pending');$('ack').textContent='ACK已確認：'+t.id+' · '+t.status}}catch(e){if(e.code){pending=null;localStorage.removeItem('wb-pending')}notify(e);$('ack').textContent=e.code?'任務被拒絕：'+e.message:'狀態未知，重連後查詢原任務ID'}finally{$('startTask').disabled=false;await refreshStatus()}}
