async function drawFrame(){if(!replay||!$('raw'))return;const token=++renderToken,r=replay.rows[frame];if(!r){textCanvas('raw',['尚無影格／事件']);textCanvas('overlay',['任務執行後重新開啟紀錄']);return}let t=r.capture_s||0;$('seek').value=frame;$('frameInfo').textContent=`影格 ${frame} / ${replay.rows.length-1} · 拍攝經過 ${t.toFixed(3)} s · 全段 ${(replay.rows.at(-1)?.capture_s||0).toFixed(3)} s（不以固定FPS縮短）`;
let ev=(replay.events||[]).filter(e=>(e.t??0)<=t).at(-1);$('eventInfo').textContent=JSON.stringify(ev||{A:r.A?.mode,B:r.B?.mode,source:r.source},null,2);
if(replay.kind==='shadow'){let im=new Image(),mask=new Image(),name=String(r.frame??frame).padStart(6,'0');im.src=`/asset/${replay.id}/${name}.jpg`;mask.src=`/asset/${replay.id}/${name}.png`;await Promise.all([im.decode(),mask.decode()]);if(token!==renderToken||!$('raw'))return;let a=$('raw').getContext('2d'),b=$('overlay').getContext('2d');a.drawImage(im,0,0,1280,720);b.drawImage(im,0,0,1280,720);let tmp=document.createElement('canvas');tmp.width=mask.naturalWidth;tmp.height=mask.naturalHeight;let ctx=tmp.getContext('2d');ctx.drawImage(mask,0,0);let pixels=ctx.getImageData(0,0,tmp.width,tmp.height);for(let i=0;i<pixels.data.length;i+=4){let on=pixels.data[i]>0;pixels.data[i]=221;pixels.data[i+1]=110;pixels.data[i+2]=193;pixels.data[i+3]=on?100:0}ctx.putImageData(pixels,0,0);b.drawImage(tmp,0,0,1280,720);let path=r[$('overlayMode').value]?.path||[];b.strokeStyle='#d6f770';b.lineWidth=5;b.beginPath();path.forEach(([x,y],i)=>i?b.lineTo(x,y):b.moveTo(x,y));b.stroke()}else{if(replay.kind==='field'&&replay.has_images){let im=new Image();im.src=`/asset/${replay.id}/${String(r.frame??frame).padStart(6,'0')}.jpg`;await im.decode();if(token!==renderToken||!$('raw'))return;$('raw').getContext('2d').drawImage(im,0,0,1280,720)}else textCanvas('raw',[replay.kind==='simulation'?'SIMULATED · 合成事件':'既有實錄 · 原始時間鏈',`t = ${t.toFixed(3)} s`,`Frame ${r.frame_id??r.frame??frame}`,replay.kind==='field'?(replay.source==='orin'?'此紀錄只有控制事件，沒有相機影像':'原始AVI未轉碼；此處不顯示影片像素'):'沒有真實相機影像']);textCanvas('overlay',replay.id.startsWith('orin-record-')?['Orin 純錄影','沒有同步車控指令紀錄','尚未執行模型／路徑分析']:[`PWM ${ev?.pwm??ev?.command?.left??'未知'} %`,`Command ${ev?.command_us??ev?.command?.steer_us??'未知'} us`,`Encoder A ${ev?.encoder_a??ev?.vehicle?.enc_a?.delta??'未知'}`,`Encoder B ${ev?.encoder_b??ev?.vehicle?.enc_b?.delta??'未知'}`,ev?.reason||'指令 ≠ 實際輪角／速度'])}}
function playLoop(){if(!playing||route!=='replay'||!replay)return;let t=playbackTime+(performance.now()-playbackStart)/1000,n=frame;while(n+1<replay.rows.length&&replay.rows[n+1].capture_s<=t)n++;if(n!==frame)moveFrame(n);if(n>=replay.rows.length-1){playing=false;if($('play'))$('play').textContent='▶ 播放';return}requestAnimationFrame(playLoop)}

async function modelsPage(){const key='comparison',d=await loadEditable(key,{dataset:'',baseline:'v4',candidate:'v5（未採用）',split:'以整段影片／場景拆分',metrics:'',notes:'',status:'待確認'});if(route!=='models')return;$('main').innerHTML=title('06','模型與算法比較','保留既有v4基準；候選評分、資料版本與人工判讀分開記錄。')+`<details ontoggle="const f=this.querySelector('iframe');if(this.open){if(!f.src)f.src=f.dataset.src}else{f.removeAttribute('src')}"><summary>展開模型實驗報告（收合會卸載，降低背景負擔）</summary><iframe id="experimentReport" title="模型實驗報告、評分與同影格回放" data-src="/experiments.html?embedded=1" style="display:block;width:100%;height:750px;border:0" scrolling="yes"></iframe></details><div class="grid"><section class="card tint"><span class="eyebrow">BASELINE</span><h1>v4 · 白線語意分割</h1><p>此卡是原部署基準的版本說明，不是模型切換按鈕。上方實驗包含 v4 與其他候選；目前沒有執行 Orin 模型替換。</p><p class="mono">8b802fa03d34fa73049b92ac5c3a6df121f94d3e9f7875103ceaf50de3424e54</p></section><section class="card"><h2>比較規則</h2><ol class="steps"><li>固定資料版本，按整段影片／場景拆分。</li><li>分開人工mask、候選mask與頁面評語。</li><li>記錄漏線、反光、邊界誤差與延遲。</li><li>路徑身份、連續性、單側／雙側與掉線分開評分。</li><li>Orin同輸入一致性／效能驗證後才能明確採用。</li></ol><a href="#replay">打開同影格 A/B 回看 →</a></section></div><section class="card" id="editor"><h2>人工比較筆記（保存在筆電）</h2><p class="note">上方是程式產生的實驗結果；這裡供你另外記錄看法、候選與限制。填寫模型名稱或保存筆記不會更動上方評分、重跑實驗，也不會切換 Orin 模型。目前尚未實作 Orin 部署／切換／回退功能。</p><div class="formgrid">${field('dataset','固定資料集版本／雜湊',d.dataset)}${field('split','拆分方式',d.split)}${field('baseline','基準版本',d.baseline)}${field('candidate','候選版本',d.candidate)}<label>評分／方法／誤差<textarea id="metrics">${esc(d.metrics)}</textarea></label><label>已知限制／回退基準<textarea id="comparisonNotes">${esc(d.notes)}</textarea></label></div>${saveBar()}<div class="ribbon">本頁保留人工比較紀錄；歷史離線訓練與評估請看研究報告，新的分析請使用離線影子測試區。CVAT 匯入匯出、部署與回退執行尚未串接。</div></section>`;const read=()=>({dataset:$('dataset').value,split:$('split').value,baseline:$('baseline').value,candidate:$('candidate').value,metrics:$('metrics').value,notes:$('comparisonNotes').value,status:'待確認'});await bindSave(key,read,modelsPage,async d=>{try{await save(key,d);notify('比較筆記已保存；沒有更換部署模型')}catch{}});$('apply').remove();$('save').textContent='保存比較筆記';$('saveDefault').textContent='保存為筆記範本';$('saveState').textContent='筆記版本 v'+(documents[key]?.rev||0)+' · 僅保存本機筆記，無部署操作'}

