window.addEventListener("message",event=>{const report=document.getElementById("experimentReport");if(event.origin!==location.origin||event.source!==report?.contentWindow||event.data?.type!=="experiment-height")return;const height=Number(event.data.height);if(Number.isFinite(height)&&height>0&&height<30000)report.style.height=Math.ceil(height)+"px"});

let orinTimer=null,orinPreviewTimer=null,orinBusy=false,orinOwnedJob=null;
function orinPanel(){return `<section class="card tint"><span class="eyebrow">ORIN · 真實設備／非模擬</span><h2>Orin 狀態、相機與純錄影</h2><p>透過 SSH 連到既有服務；只查狀態、讀相機、操作本工作台建立的純錄影。下方模擬按鈕不控制實車。</p><div id="orinState" role="status">正在查詢 Orin…</div><div class="actions"><button id="orinRefresh" class="secondary">重新查詢狀態</button><button id="orinPhoto" class="secondary">相機單張預覽</button><button id="orinPreview" class="ghost">開始連續預覽</button></div><p id="orinCameraNote" class="note">預覽預設關閉；影像是 Orin 相機原始快照，沒有模型疊圖。</p><img id="orinCamera" alt="Orin 相機快照" style="max-width:720px;width:100%;display:none"><details><summary>純錄影與紀錄同步</summary><p>純錄影不送轉向或動力命令。Orin 自行計時，關閉筆電頁面仍會到時結束；最多120秒。若已有錄影，拒絕新增，不中斷既有錄影。</p><label>錄影秒數 <input id="orinSeconds" type="number" min="1" max="120" value="10"></label><div class="actions"><button id="orinRecord">開始 Orin 純錄影</button><button id="orinRecordStop" class="secondary">提前結束本工作台錄影</button><button id="orinDiscover" class="ghost">更新 Orin 紀錄清單</button><button id="orinSync" class="secondary">同步已完成紀錄到筆電</button></div><p id="orinAction" role="status"></p><div id="orinRecords"></div><p>同步為單向下載與 SHA256 核對，保留原始影片、時間戳及影子評語。重複同步不覆蓋舊版本；同步完成後可在「錄影與回放」選取 Orin 紀錄。筆電人工筆記不會回寫 Orin。</p></details></section>`}
async function orinCameraOnce(){if(!$('orinCamera'))return;const img=$('orinCamera'),note=$('orinCameraNote');note.textContent='正在取得新快照…';try{const res=await fetch('/orin-camera.jpg',{cache:'no-store'});if(!res.ok)throw Error('相機暫時無法讀取');const blob=await res.blob();if(!blob.type.startsWith('image/'))throw Error('相機未回傳影像');const url=URL.createObjectURL(blob);await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});URL.revokeObjectURL(url);img.style.display='block';note.textContent='收到 Orin 相機影像：'+new Date().toLocaleTimeString()+' · 原始快照，非模型結果'}catch{img.style.display='none';note.textContent='相機連線失敗；舊影像已隱藏，不當作即時畫面'}}
async function orinUpdate(){if(document.hidden||orinBusy||!$('orinState'))return;orinBusy=true;try{const s=await api('/api/orin/status');if(!$('orinState'))return;if(!s.connected){$('orinState').innerHTML='<div class="ribbon">Orin 離線／狀態未知：'+esc(s.error)+'</div>';orinOwnedJob=null;$('orinRecord').disabled=true;$('orinRecordStop').disabled=true;return}const v=s.vehicle||{},rec=s.recording?.current;const active=s.jobs?.find(j=>['queued','recording','stop_pending'].includes(j.state));orinOwnedJob=active?.job||null;$('orinState').innerHTML=`<div class="grid three"><div><b>車輛 ${esc(v.state||'未知')}</b><p>韌體 ${esc(v.fw||'未知')}<br>原因 ${esc(v.reason||'未知')}</p></div><div><b>相機資料年齡 ${esc(s.telemetry?.camera_age_s)} 秒</b><p>通訊資料年齡 ${esc(s.telemetry?.uart_age_s)} 秒<br>UART 由原服務管理；工作台不開啟串口。</p></div><div><b>兩輪指令 ${esc(v.motor_a?.pwm_command??'未知')} / ${esc(v.motor_b?.pwm_command??'未知')}</b><p>錄影 ${rec?.status==='recording'?'進行中 · '+esc(rec.frames)+' 影格':'未錄影'}<br>磁碟可用 ${(s.disk_free_bytes/1024**3).toFixed(1)} GiB</p></div></div><p class="note">主機 ${esc(s.host)} · 查詢 ${new Date(s.at*1000).toLocaleTimeString()} · 電壓 ${esc(v.voltage_v??'未知')}／電流 ${esc(v.current_a??'未知')}／速度 ${esc(v.speed_mps??'未知')}（未知不當作0）</p><details><summary>服務狀態與最近錄影工作</summary><pre>${esc(s.services)}
${esc(JSON.stringify(s.jobs,null,2))}</pre></details>`;$('orinRecord').disabled=rec?.status==='recording'||!!active;$('orinRecordStop').disabled=!active;
const data=await api('/api/orin/records');if(!$('orinRecords'))return;const sync=data.sync;$('orinRecords').innerHTML=`<p>同步狀態：${esc(sync.state)} · ${sync.completed||0}/${sync.total||0} · ${esc(sync.current||'')}</p>${sync.errors?.length?'<pre>'+esc(JSON.stringify(sync.errors,null,2))+'</pre>':''}<p>Orin 清單 ${data.records.length} 筆；筆電已驗證 ${data.local.length} 筆。</p><p>同步完成後重新進入本分頁，即可在下方選取新增紀錄。</p><div id="orinPaged"></div>`;
pagedList('orinPaged',data.records,r=>`<article class="record-row">${esc(r.kind)} / ${esc(r.id)} · ${(r.bytes/1024**2).toFixed(1)} MiB · ${data.local.some(x=>x.kind===r.kind&&x.id===r.id)?'已有本機版本':'尚未同步'}</article>`)

}catch(e){if($('orinState'))$('orinState').textContent='查詢失敗：'+e.message}finally{orinBusy=false}}
async function bindOrin(){LastInputs.bind('orin-record',['orinSeconds']);const orinHost=$('orinState');const run=async(fn)=>{try{const result=await fn();if($('orinAction'))$('orinAction').textContent=JSON.stringify(result);await orinUpdate()}catch(e){if($('orinAction'))$('orinAction').textContent=e.message;notify(e)}};$('orinRefresh').onclick=orinUpdate;$('orinPhoto').onclick=orinCameraOnce;$('orinPreview').onclick=()=>{const img=$('orinCamera'),note=$('orinCameraNote');if(orinPreviewTimer||img.dataset.stream){clearInterval(orinPreviewTimer);orinPreviewTimer=null;img.dataset.stream='';img.onerror=null;img.removeAttribute('src');$('orinPreview').textContent='開始連續預覽';note.textContent='連續預覽已關閉。';return}const fallback=()=>{if(!img.dataset.stream)return;img.dataset.stream='';img.onerror=null;note.textContent='連續串流不可用（車控入口未連線或相機未更新），改用每3秒單張快照。';let pending=false;const take=async()=>{if(pending)return;pending=true;try{await orinCameraOnce()}finally{pending=false}};take();orinPreviewTimer=setInterval(take,3000)};img.dataset.stream='1';img.onerror=fallback;img.hidden=false;img.src='/vehicle/camera.mjpg?t='+Date.now();note.textContent='連續預覽：Orin相機最新影像串流（只送最新一張、不排隊），實際幀率依網路；沒有模型疊圖，不代表PID控制影像年齡。';$('orinPreview').textContent='關閉連續預覽'};$('orinRecord').onclick=()=>run(()=>api('/api/orin/record/start',{job:crypto.randomUUID().replaceAll('-',''),duration_s:Number($('orinSeconds').value)}));$('orinRecordStop').onclick=()=>run(()=>{if(!orinOwnedJob)throw Error('沒有可停止的本工作台錄影');return api('/api/orin/record/stop',{job:orinOwnedJob})});$('orinDiscover').onclick=()=>run(()=>api('/api/orin/discover',{}));$('orinSync').onclick=()=>run(()=>api('/api/orin/sync',{all:true}));await orinUpdate();if(orinHost?.isConnected)orinTimer=setInterval(orinUpdate,6000)}
function attendancePanel(){return `<section class="card"><h2>實機接替進度與需要你在場的項目</h2><div id="orinAcceptance" class="ribbon">正在讀取通路驗收摘要…</div><table><tr><th>功能</th><th>目前通路／驗收範圍</th></tr><tr><td>狀態、相機、純錄影</td><td>本工作台透過 SSH 連到 Orin 既有服務；純錄影獨立計時，不發出車控命令。</td></tr><tr><td>錄影、影子結果、評語</td><td>單向同步到筆電並核對雜湊；可在模型分頁選影片及模型重跑離線分析、比較與保存區間評語。原始資料保留。</td></tr><tr><td>車身設定、校準與手動任務</td><td>車身幾何仍是筆電草稿；實車舵機、馬達與手動設定已接入校準／手動分頁的實車面板。</td></tr><tr><td>模型部署、切換、回退</td><td>尚未接入；離線結果不會自動替換 v4。</td></tr><tr><td>舊網站接替</td><td>8000 操作台／手動與 8091 影子分析已從新工作台接通；舊後端保留。Notebook 也在模型分頁；CVAT／field-6 沒有運行中的來源服務，未標示已接替。</td></tr></table><details><summary>查看實際通路驗收</summary><p><a href="/api/orin/acceptance" target="_blank">新工作台端到端驗收</a> · <a href="/api/orin/audit" target="_blank">舊網站唯讀端點與登入保護核對</a></p><p>8000 狀態／相機／錄影及 8091 影子頁可讀；8092 場地控制目前未啟動，本次不啟動它。</p></details><h3>等你在場再做</h3><ul><li>目前相機快照很暗；確認鏡頭遮擋、光線與構圖後，再評估畫面品質。</li><li>確認場地無人、車輪與急停可用，再做馬達方向、速度與停止測試。</li><li>舵機方向、回正、輪角極限與機械干涉檢查。</li><li>車身尺寸、地面與相機幾何標定；改裝後重新量測。</li><li>燒錄、開啟 UART 或重啟車控可能造成回正，須另行安排。</li><li>閉環行駛與路口判斷，需要現場監看與立即急停能力。</li></ul><p class="note">通路可讀、錄影成功或模型有路徑，都不能取代上述實車驗證。新工作台沿用原控制後端；本次入口整合不等於完成實車幾何及行駛驗證，舊服務仍保留。</p></section>`}
