const simulatedDrivePage=drivePage;drivePage=async()=>{await simulatedDrivePage();if(route==='drive')$('main').insertAdjacentHTML('afterbegin','<section class="card tint"><h2>開發測試說明</h2><p>實車控制已接在上方面板；狀態、真實相機與純錄影也可由總覽及錄影分頁操作。下方模擬區的 PWM、開始與停止只作用在筆電模擬器；上方實車面板與頂端「實車停止」會控制 Orin。</p><a class="button secondary" href="#replay">前往 Orin 純錄影與同步 →</a></section>')};

async function renderOrinAcceptance(){if(!$('orinAcceptance'))return;try{const r=await api('/api/orin/acceptance');if(!$('orinAcceptance'))return;if(r.state!=='completed'){$('orinAcceptance').textContent='驗收尚未完成';return}const b=r.replay_breakdown||{};$('orinAcceptance').innerHTML=`<b>通路驗收完成 · ${new Date(r.completed_at*1000).toLocaleString()}</b><p>80 筆來源紀錄已核對同步；${b.image_records??35} 筆有影像、${b.event_only_records??44} 筆僅控制事件、${b.empty_event_records??1} 筆原始空紀錄。10 秒 Orin 自行計時錄影、提前結束與重疊錄影拒絕已測試通過。</p><p>原服務啟動時間與重啟次數未變，車輛維持 LOCKED、兩輪指令／目標為0。相機通路可讀，但畫面很暗，光線／遮擋待現場確認。</p><p>資料限制：一筆舊控制檔尾行截斷，回放保留其他有效事件並顯示警告；另一筆原始紀錄為空。原檔均完整保留，不補造資料。</p>`}catch(e){if($('orinAcceptance'))$('orinAcceptance').textContent='驗收摘要讀取失敗：'+e.message}}

// Keep the page title and a compact section navigator above late-loaded panels.
(()=>{
 const main=document.getElementById('main');let queued=false,sectionSequence=0;
 function arrange(){queued=false;const heading=main.querySelector(':scope > .heading');if(!heading)return;
  if(main.firstElementChild!==heading)main.prepend(heading);
  let jump=main.querySelector(':scope > .page-jumps');
  if(!jump){jump=document.createElement('div');jump.className='page-jumps';jump.innerHTML='<label for="pageSectionJump">跳到本頁區塊</label><select id="pageSectionJump"><option value="">選擇要查看的內容…</option></select>';heading.after(jump);jump.querySelector('select').onchange=e=>{const target=document.getElementById(e.target.value);if(target){if(target.matches('details'))target.open=true;target.scrollIntoView({block:'start'});target.setAttribute('tabindex','-1');target.focus({preventScroll:true});}e.target.value='';};}
  if(heading.nextElementSibling!==jump)heading.after(jump);
  const currentReview=main.querySelector(':scope > #threeZoneReview');
  const corridorReport=main.querySelector(':scope > #corridorMemoryReport');
  if(corridorReport){if(jump.nextElementSibling!==corridorReport)jump.after(corridorReport);}
  else if(currentReview&&jump.nextElementSibling!==currentReview)jump.after(currentReview);
  const sections=[...main.children].filter(x=>x!==heading&&x!==jump&&!x.hidden&&(x.querySelector('h2')||x.matches('details')));
  const entries=sections.map((section,i)=>{if(!section.id){let id;do{id='page-section-'+(++sectionSequence)}while(document.getElementById(id));section.id=id;}return [section.id,(section.matches('details')?section.querySelector('summary'):section.querySelector('h2')||section.querySelector('summary')).textContent.trim()];});
  const signature=JSON.stringify(entries);if(jump.dataset.signature!==signature){jump.dataset.signature=signature;const select=jump.querySelector('select');select.replaceChildren(new Option('選擇要查看的內容…',''),...entries.map(([id,title])=>new Option(title,id)));}
 }
 new MutationObserver(()=>{if(!queued){queued=true;requestAnimationFrame(arrange);}}).observe(main,{childList:true,subtree:true});arrange();
})();

async function renderPidOfflineAudit(page){
 const r=await api('/experiment/pid-offline-integration/report.json');
 if(route!==page)return;
 const total=r.replays.reduce((n,x)=>n+x.frames,0);
 const brief=`<h2>${esc(r.title)}</h2><p class="note">${esc(r.checked_at)} · 保存的本機驗證結果</p><div class="ribbon">${r.passed?'通過':'未通過'} ${esc(r.tests)} 項測試 · ${esc(r.cases.length)} 種串流情境 · ${total} 張既有影片路徑。僅本機候選修補，尚未部署 Orin；新算法實車控制仍禁用。</div>`;
 if(page==='overview'){
  $('main').insertAdjacentHTML('beforeend',`<section class="card" id="pidOfflineSummary">${brief}<p>已補上倒退影格、擷取時間與權重身分檢查，假控制端驗證故障停止。這是軟體接入驗證；實際延遲、場地品質與車輪響應仍待驗證。</p><a href="#models">在 06 查看串流情境、影片提案與限制</a></section>`);
  return;
 }
 const labels={healthy:'正常連續輸入',seq:'模型回覆錯序',model:'模型身分不符',algorithm:'算法身分不符',weights:'權重雜湊改變',invalid:'路徑標記無效',blank:'遮罩全空',nan_path:'路徑含非有限數值',missing_row:'缺少前視列',inference_delay:'推論延遲超限',crash:'模型程序退出',timeout:'模型回覆逾時',camera_missing:'相機無影像',camera_stale:'相機影像過期',duplicate_frame:'重複影格直至過期',backward_frame:'影格編號倒退',future_capture:'未來擷取時間',nan_capture:'非有限擷取時間',sink_reject:'假控制端拒絕',sink_stopped:'假控制端已停止',browser_lost:'瀏覽器租約失效',deadline:'限時到期',protocol:'協定版本不符',low_quality:'低品質且標記失效',repeated_capture:'擷取時間未遞增'};
 const list=items=>'<ul>'+items.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>';
 $('main').insertAdjacentHTML('afterbegin',`<section class="card" id="pidOfflineDetails">${brief}<h3>連續串流到假控制端</h3><p>每個異常案例先通過三張正常影格，接著注入故障。測試檢查停止請求及停止後無新增控制派送；正常案例最後由測試結束。下列提案只送到記憶體假控制端。</p><div style="max-height:320px;overflow:auto"><table><thead><tr><th>情境</th><th>假控制端提案數</th><th>停止原因</th></tr></thead><tbody>${r.cases.map(x=>`<tr><td>${esc(labels[x.case]||x.case)}</td><td>${x.fake_commands}</td><td>${esc(x.stop_reason)}</td></tr>`).join('')}</tbody></table></div><h3>既有影片路徑接入 PID</h3><p>使用1360µs中心、影像座標及固定參數重算。沒有重新推論模型或套用v7幾何。丟線後繼續重算只是離線診斷，實車停止後不會自動重啟。</p><table><tr><th>來源紀錄</th><th>影格</th><th>有效提案</th><th>暖機</th><th>前視列無路徑</th></tr>${r.replays.map(x=>`<tr><td>${esc(x.run.slice(0,8))}</td><td>${x.frames}</td><td>${x.proposals}</td><td>${x.reasons.WARMUP||0}</td><td>${x.reasons.NO_PATH_AT_LOOKAHEAD||0}</td></tr>`).join('')}</table><p>有效提案數不是準確率，也不能推算新命令下的軌跡、圈速或成功率。</p><h3>本機修補與未完成項目</h3>${list(r.fixes)}${list(r.limitations)}<details><summary>方法與可追溯資料</summary>${list(r.method)}<p><a href="/experiment/pid-offline-integration/report.json" target="_blank">驗證結果與原始碼 SHA256</a></p>${r.replays.map(x=>`<p><a href="/experiment/pid-offline-integration/${esc(x.run)}.json" target="_blank">${esc(x.run.slice(0,8))} 逐影格提案</a> · 來源 SHA256 <span class="mono">${esc(x.source_sha256)}</span></p>`).join('')}</details></section>`);
}
