async function renderV7PidReport(page){
 const r=await api('/experiment/v7-pid-integration/report.json');if(route!==page)return;
 const summary=`<h2>${esc(r.title)}</h2><div class="ribbon">${r.switch_update?`切換v1：${r.switch_update.passed?'通過':'未通過'} ${r.switch_update.tests} 項差異測試；原95項與前端11項未重跑`:`先前筆電驗證 ${r.tests} 項`} · 部署包已準備，尚未部署Orin、未動車。</div>`;
 const list=a=>'<ul>'+a.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>';
 if(page==='overview'){$('main').insertAdjacentHTML('afterbegin',`<section class="card" id="v7PidSummary">${summary}<p>本次主線是校正v7接入路徑與視覺PID，不是temporal-v2預覽。已完成本機候選與部署準備；目前停在這個階段，等你確認後續。</p><a href="#models">06 查看v7原始快照路徑、PID提案與部署準備</a><details><summary>後續部署步驟</summary>${list(r.deployment_steps)}</details></section>`);return;}
 $('main').insertAdjacentHTML('afterbegin',`<section class="card" id="v7PidDetails">${summary}<p>v7量測原檔固定為SHA256 <span class="mono">${esc(r.calibration_sha256)}</span>。辨識沿用V4；雙線取中心、單線向內偏移23cm，路徑再轉回影像座標交給既有視覺PID。</p><h3>目前姿態的v7快照：三種路徑</h3><p>同一張快照，單線案例由遮罩保留單側；綠色為路徑、黃色為近列0.60。重複輸入只驗證確認邏輯，沒有假稱為連續實車影片。</p><div class="grid three">${r.snapshot_observations.map(x=>`<article><h3>${esc(({double:'雙線中心',left:'僅左線',right:'僅右線'})[x.mode])}</h3><img loading="lazy" style="width:100%" src="/experiment/v7-pid-integration/${esc(x.image)}" alt="v7 ${esc(x.mode)}路徑"><p>路徑${x.result.valid?'有效':'無效'} · PID提案${x.proposal.valid?'有效':'無效'}<br>提案 ${x.proposal.steer_us?.toFixed(1)??'—'}µs（假控制端，非實車輸出）</p></article>`).join('')}</div>${r.restriction_audit?`<h3>2026-10-21 限制檢閱與完整流程</h3><p>${esc(r.restriction_audit.scope)}</p>${r.restriction_audit.findings.map(f=>`<details><summary>${esc(f.item)} · ${esc(f.classification)}</summary><p>${esc(f.evidence)}</p><p>${esc(f.action)}</p></details>`).join('')}<h3>連線 → 部署 → 試跑</h3><ol>${r.restriction_audit.workflow.map(x=>'<li>'+esc(x)+'</li>').join('')}</ol><p>${esc(r.restriction_audit.authorization)}</p>`:''}${r.entry_gate_update?`<h3>前端門檻修正</h3>${list(r.entry_gate_update.changes)}<p>${esc(r.entry_gate_update.scope)}</p><a href="/experiment/v7-pid-integration/entry-gates-tests.json" target="_blank">先前11項前端差異測試</a>`:''}${!r.switch_update&&r.switch_proposal?`<h3>雙／單線切換方案（尚未實作）</h3><p>${esc(r.switch_proposal.current)}</p>${list(r.switch_proposal.steps)}<p>${esc(r.switch_proposal.first_iteration)}</p>`:''}${r.switch_update?`<h3>雙／單線切換 v1（已實作，待部署）</h3>${list(r.switch_update.changes)}<h4>當張候選品質診斷</h4><p>以下為v7快照遮罩模擬掉線；連續有效張數不等於準確率。正式worker每張回傳同樣欄位。</p>${r.switch_update.snapshot_diagnostics.map(x=>`<h4>保留${x.side==='left'?'左':'右'}線：${esc(x.transition)} · PID提案${x.pid_valid?'有效':'無效'}</h4><table><tr><th>候選</th><th>當張可用／備妥</th><th>連續張數</th><th>範圍cm</th><th>邊界RMS cm</th><th>相鄰變化cm</th></tr>${Object.entries(x.candidates).map(([k,d])=>`<tr><td>${esc(k)}</td><td>${d.usable?'可用':'無效'}／${d.ready?'備妥':'未備妥'}</td><td>${d.consecutive_valid}</td><td>${d.support_cm?.map(v=>v.toFixed(1)).join('～')??'—'}</td><td>${Object.entries(d.boundary_fits).map(([side,f])=>esc(side)+': '+(f.residual_cm?.toFixed(2)??'—')+' ('+esc(f.reason)+')').join('<br>')}</td><td>${d.change_cm?.toFixed(2)??'—'}</td></tr>`).join('')}</table>`).join('')}${list(r.switch_update.limitations)}<a href="/experiment/v7-pid-integration/switch-tests.json" target="_blank">8項差異測試與逐張切換紀錄</a>`:''}<h3>已完成的接入</h3>${list(r.completed)}<p>近列0.60約對應${r.recommended_rows.near_reference_cm.toFixed(1)}cm，遠列0.50約${r.recommended_rows.far_reference_cm.toFixed(1)}cm，距離參考仍是前輪輪胎最前緣。原0.75列超出50～120cm範圍會被拒絕；不自動修改你保存的PID參數。</p><details><summary>先前版本v7串流故障驗證 ${r.stream_cases.length} 種情境（本次未重跑）</summary><div style="max-height:320px;overflow:auto"><table><tr><th>情境</th><th>假控制提案</th><th>停止原因</th></tr>${r.stream_cases.map(x=>`<tr><td>${esc(x.case)}</td><td>${x.fake_commands}</td><td>${esc(x.stop_reason)}</td></tr>`).join('')}</table></div></details><h3>尚未驗證與限制</h3>${list(r.limitations)}<details><summary>部署準備與可追溯資料</summary>${list(r.deployment_steps)}<p>套件：${esc(r.bundle?.path||'未產生')}<br>SHA256：<span class="mono">${esc(r.bundle?.sha256||'—')}</span></p><a href="/experiment/v7-pid-integration/report.json" target="_blank">完整報告</a> · <a href="/experiment/v7-pid-integration/manifest.json" target="_blank">部署檔案清單與SHA256</a></details></section>`);
}
